/* Isogeny Evidence Lab — single-page frontend (vanilla JS, hash routing). */
const API = "";
const $ = (s, r = document) => r.querySelector(s);
const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const fmt = (v) => v === null || v === undefined ? '<span class="na">—</span>' : typeof v === "number" ? (Number.isInteger(v) ? v : v.toPrecision(4)) : esc(v);
const badge = (s, extra = "") => `<span class="badge b-${esc(s)} ${extra}">${esc(String(s || "").replace(/_/g, " "))}</span>`;
const prov = (p) => `<span class="prov ${esc(p)}">${esc(p)}</span>`;
const demo = (x) => x ? badge("demo") : "";
const passmark = (p) => p === true ? '<span class="ok">pass</span>' : p === false ? '<span class="bad">FAIL</span>' : '<span class="na">n/a</span>';
const when = (s) => s ? new Date(s).toLocaleString() : "—";
const nl = (arr) => (arr && arr.length) ? `<ul class="tight">${arr.map(x => `<li>${esc(typeof x === "string" ? x : JSON.stringify(x))}</li>`).join("")}</ul>` : '<span class="na">none</span>';
const json = (o) => `<pre>${esc(JSON.stringify(o, null, 1))}</pre>`;
let TOKEN = localStorage.getItem("iel_token"), ME = null;

function staticApi(path, opts) {
  const S = window.IEL_STATIC;
  if ((opts.method || "GET") !== "GET") throw new Error("Read-only static demo: changes are disabled here. Run the app locally (see README) to use the full workflow.");
  if (path === "/api/auth/me") return Promise.resolve(S.get["/api/auth/me"]);
  const v = S.get[path];
  if (v === undefined) return Promise.reject(new Error("Not part of the static snapshot: " + path));
  return Promise.resolve(JSON.parse(JSON.stringify(v)));
}
async function api(path, opts = {}) {
  if (window.IEL_STATIC) return staticApi(path, opts);
  const headers = {"Content-Type": "application/json", ...(TOKEN ? {Authorization: "Bearer " + TOKEN} : {})};
  if (opts.body && typeof opts.body !== "string" && !(opts.body instanceof FormData)) opts.body = JSON.stringify(opts.body);
  if (opts.body instanceof FormData) delete headers["Content-Type"];
  const r = await fetch(API + path, {...opts, headers});
  if (r.status === 401) { TOKEN = null; localStorage.removeItem("iel_token"); render(); throw new Error("not signed in"); }
  if (!r.ok) { let m = r.statusText; try { m = (await r.json()).detail || m; } catch {} throw new Error(typeof m === "string" ? m : JSON.stringify(m)); }
  const ct = r.headers.get("content-type") || "";
  return ct.includes("json") ? r.json() : r;
}
function toast(msg, bad = false) { const d = document.createElement("div"); d.className = "callout " + (bad ? "bad" : "info"); d.style.cssText = "position:fixed;bottom:20px;right:20px;max-width:420px;z-index:9"; d.textContent = msg; document.body.appendChild(d); setTimeout(() => d.remove(), 5000); }
async function act(fn, ok = "Done") { try { await fn(); toast(ok); render(); } catch (e) { toast(e.message, true); } }
window.act = act;

// ------------------------------------------------------------------ router
const routes = [];
const route = (re, fn) => routes.push([re, fn]);
async function render() {
  const app = $("#app");
  if (window.IEL_STATIC && !TOKEN) TOKEN = "static-demo";
  if (!TOKEN) { $("#projnav").innerHTML = ""; $("#whoami").textContent = ""; return app.innerHTML = loginView(); }
  if (!ME) { try { ME = await api("/api/auth/me"); } catch { return; } }
  $("#whoami").textContent = `${ME.name}${ME.is_admin ? " (admin)" : ""}`;
  const hash = location.hash.replace(/^#/, "") || "/";
  const [path, qs] = hash.split("?");
  const q = Object.fromEntries(new URLSearchParams(qs || ""));
  for (const [re, fn] of routes) { const m = path.match(re); if (m) { app.innerHTML = '<p class="muted">Loading…</p>'; try { app.innerHTML = await fn(...m.slice(1), q); } catch (e) { app.innerHTML = `<div class="callout bad">${esc(e.message)}</div>`; } return; } }
  app.innerHTML = "<p>Not found.</p>";
}
window.addEventListener("hashchange", render);
$("#logout").onclick = async () => { if (window.IEL_STATIC) return toast("Static demo: signed in as the seeded demo engineer (read-only)."); try { await api("/api/auth/logout", {method: "POST"}); } catch {} TOKEN = null; ME = null; localStorage.removeItem("iel_token"); location.hash = "#/"; render(); };

function loginView() {
  setTimeout(() => { $("#loginform").onsubmit = async (e) => { e.preventDefault(); try { const r = await api("/api/auth/login", {method: "POST", body: {email: $("#email").value, password: $("#password").value}}); TOKEN = r.token; localStorage.setItem("iel_token", TOKEN); ME = r.user; render(); } catch (err) { $("#loginerr").textContent = err.message; } }; });
  return `<div class="panel login"><h1>Sign in</h1><p class="sub">Isogeny Evidence Lab</p>
  <form id="loginform"><label>Email</label><input id="email" value="engineer@customer.local"><label>Password</label><input id="password" type="password" value="engineer-demo-password">
  <p class="err" id="loginerr"></p><button>Sign in</button></form>
  <p class="muted" style="font-size:12px;margin-top:14px">Demo accounts (seeded): engineer@customer.local (editor), reviewer@isogeny.local (reviewer), admin@isogeny.local (admin). Passwords: <code>&lt;role&gt;-demo-password</code>.</p></div>`;
}

function projNav(pid, cur) {
  const items = [["", "Overview"], ["/inventory", "Inventory"], ["/recommendations", "Recommendations"], ["/implementations", "Implementation"], ["/runs", "Evidence"], ["/compare", "Compare"], ["/research", "Research inbox"], ["/attack", "Attack cost"], ["/sandbox", "Sandbox"], ["/revalidation", "Revalidation"], ["/audit", "Audit"]];
  $("#projnav").innerHTML = items.map(([p, l]) => `<a href="#/p/${pid}${p}" class="${cur === p ? "active" : ""}">${l}</a>`).join("");
}

// ------------------------------------------------------------------ portfolio
route(/^\/$/, async () => {
  $("#projnav").innerHTML = "";
  const ps = await api("/api/projects");
  return `<h1>Portfolio</h1><p class="sub">Projects under continuous assurance. Counts come from append-only run records and open findings, not a score.</p>
  <div class="panel"><table><tr><th>Project</th><th>Kind</th><th>Implementations</th><th>Runs (failed)</th><th>Open findings</th><th>Pending recommendations</th><th>Last run</th></tr>
  ${ps.map(p => `<tr class="clickable" onclick="location.hash='#/p/${p.id}'"><td><b>${esc(p.name)}</b> ${demo(p.is_demo)}<br><span class="muted">${esc(p.business_purpose)}</span></td><td>${esc(p.kind)}</td><td>${p.counts.implementations}</td><td>${p.counts.runs} (<span class="${p.counts.runs_failed ? "bad" : ""}">${p.counts.runs_failed}</span>)</td><td class="${p.counts.findings_open ? "warn" : ""}">${p.counts.findings_open}</td><td>${p.counts.recommendations_pending}</td><td>${p.last_run ? `#${p.last_run.sequence} ${passmark(p.last_run.overall_pass)} ${prov(p.last_run.provenance)}` : "—"}</td></tr>`).join("")}</table></div>
  <div class="panel"><h2>New project</h2><form onsubmit="return newProject(event)"><div class="grid g3"><div><label>Name</label><input name="name" required></div><div><label>Kind</label><select name="kind"><option value="iot">IoT / embedded device</option><option value="application">Application / SaaS service</option></select></div><div><label>Support period end</label><input name="support_period_end" placeholder="2035-12-31"></div></div>
  <div class="grid g2"><div><label>Business purpose</label><input name="business_purpose"></div><div><label>Deployment environment</label><input name="deployment_environment"></div><div><label>Data-protection requirements</label><input name="data_protection_requirements"></div><div><label>Existing update / deployment process</label><input name="update_process"></div></div>
  <label>Platform (JSON: hardware, os, software_versions, bootloader_supported_families, signature_slot_bytes…)</label><textarea name="platform">{"hardware": "", "os": "", "software_versions": {}}</textarea><p><button>Create project</button></p></form></div>`;
});
window.newProject = (e) => { e.preventDefault(); const f = new FormData(e.target); const b = Object.fromEntries(f.entries()); try { b.platform = JSON.parse(b.platform || "{}"); } catch { return toast("platform must be JSON", true); } if (!b.support_period_end) delete b.support_period_end; return act(async () => { const p = await api("/api/projects", {method: "POST", body: b}); location.hash = `#/p/${p.id}/inventory`; }, "Project created"), false; };

// ------------------------------------------------------------------ project overview
route(/^\/p\/([^/]+)$/, async (pid) => {
  projNav(pid, "");
  const o = await api(`/api/projects/${pid}/overview`);
  const p = o.project;
  return `<h1>${esc(p.name)} ${demo(p.is_demo)}</h1><p class="sub">${esc(p.kind === "iot" ? "IoT / embedded device" : "Application / SaaS service")} · support until ${esc(p.support_period_end || "n/a")} · ${esc(p.deployment_environment)}</p>
  <div class="grid g4">
    <div class="panel"><h2>What changed</h2>${o.what_changed.length ? `<table>${o.what_changed.map(x => `<tr><td>${esc(x.implementation)}${x.parent ? `<br><span class="muted">replaces ${esc(x.parent)}</span>` : ""}</td><td>${badge(x.role)} ${badge(x.status)}</td></tr>`).join("")}</table>` : '<p class="muted">No implementations yet.</p>'}</div>
    <div class="panel"><h2>What did we test</h2>${o.what_tested.length ? `<table>${o.what_tested.map(x => `<tr class="clickable" onclick="location.hash='#/p/${pid}/runs'"><td>#${x.run} ${esc(x.implementation)}<br><span class="muted">${prov(x.provenance)}</span></td><td>${passmark(x.overall_pass)}${x.failed_requirements.length ? `<br><span class="bad" style="font-size:11px">${esc(x.failed_requirements.join(", "))}</span>` : ""}</td></tr>`).join("")}</table>` : '<p class="muted">No runs yet.</p>'}</div>
    <div class="panel"><h2>What did we learn</h2>${o.what_learned.length ? `<table>${o.what_learned.map(f => `<tr class="clickable" onclick="location.hash='#/p/${pid}/findings/${f.id}'"><td>${esc(f.title)} ${demo(f.is_demo)}<br><span class="muted">${esc(f.origin)}</span></td><td>${badge(f.status)}</td></tr>`).join("")}</table>` : '<p class="muted">No open findings.</p>'}</div>
    <div class="panel"><h2>What should engineering do next</h2>${o.next_actions.length ? `<ul class="tight">${o.next_actions.map(a => `<li><a href="#/p/${pid}/${a.kind === "finding" ? "findings" : a.kind === "recommendation" ? "recommendations" : "implementations"}/${a.ref}">${esc(a.action)}</a><br><span class="muted">${esc(a.label)}</span></li>`).join("")}</ul>` : '<p class="muted">Nothing pending.</p>'}</div>
  </div>
  <div class="panel"><h2>Operational requirements — latest evidence per implementation</h2><table><tr><th>Requirement</th><th>Limit</th><th>Applies to</th><th>Latest observations</th></tr>
  ${o.requirements.map(r => `<tr><td>${esc(r.name)}<br><span class="muted">${esc(r.rationale)}</span></td><td><code>${esc(r.metric)} ${esc(r.operator)} ${r.threshold} ${esc(r.unit)}</code></td><td>${esc(r.applies_to)}</td><td>${r.latest.length ? r.latest.map(l => `${esc(l.implementation)}: ${fmt(l.observed)} ${passmark(l.pass)} ${prov(l.provenance)}`).join("<br>") : '<span class="na">no evidence</span>'}</td></tr>`).join("")}</table></div>
  <div class="grid g2"><div class="panel"><h2>Recent approvals</h2>${o.recent_approvals.length ? `<table>${o.recent_approvals.map(a => `<tr><td>${esc(a.subject_type)}</td><td>${badge(a.decision)}</td><td>${esc(a.note)}</td><td class="muted">${when(a.created_at)}</td></tr>`).join("")}</table>` : '<p class="muted">None.</p>'}</div>
  <div class="panel"><h2>Recent activity</h2><ul class="tight timeline">${o.recent_audit.map(a => `<li><span class="muted">${when(a.created_at)}</span> ${esc(a.action)} <span class="muted">${esc(a.subject_type)}</span></li>`).join("")}</ul></div></div>
  <p><a href="/api/projects/${pid}/export" onclick="return dl(event,'/api/projects/${pid}/export','evidence.zip')"><button class="ghost">Export reproducible evidence package (zip)</button></a></p>`;
});
window.dl = (e, url, name) => { e.preventDefault(); const sf = window.IEL_STATIC && window.IEL_STATIC.files[url]; fetch(sf || url, sf ? {} : {headers: {Authorization: "Bearer " + TOKEN}}).then(async r => { if (!r.ok) throw new Error(await r.text()); const b = await r.blob(); const a = document.createElement("a"); a.href = URL.createObjectURL(b); a.download = (r.headers.get("content-disposition") || "").match(/filename="([^"]+)"/)?.[1] || name; a.click(); toast("Downloaded. SHA-256: " + r.headers.get("X-SHA256")); }).catch(err => toast(err.message, true)); return false; };

// ------------------------------------------------------------------ inventory
route(/^\/p\/([^/]+)\/inventory$/, async (pid) => {
  projNav(pid, "/inventory");
  const [p, items, reqs] = await Promise.all([api(`/api/projects/${pid}`), api(`/api/projects/${pid}/inventory`), api(`/api/projects/${pid}/requirements`)]);
  return `<h1>Project &amp; cryptographic inventory</h1><p class="sub">Every fact carries its provenance. <b>Identifying an algorithm does not establish that its implementation is secure.</b> Private keys are never uploaded.</p>
  <div class="grid g2"><div class="panel"><h2>Project record</h2><dl class="kv"><dt>Business purpose</dt><dd>${esc(p.business_purpose)}</dd><dt>Deployment</dt><dd>${esc(p.deployment_environment)}</dd><dt>Support period end</dt><dd>${esc(p.support_period_end || "—")}</dd><dt>Data protection</dt><dd>${esc(p.data_protection_requirements)}</dd><dt>Update / deployment process</dt><dd>${esc(p.update_process)}</dd><dt>Members</dt><dd>${p.members.map(m => `${esc(m.email)} (${esc(m.role)})`).join(", ")}</dd></dl></div>
  <div class="panel"><h2>Platform (hardware / OS / software versions)</h2>${json(p.platform)}</div></div>
  <div class="panel"><h2>Cryptographic facts</h2><table><tr><th>Category</th><th>Name</th><th>Purpose</th><th>Parameters / version</th><th>Provenance</th><th>Notes</th><th></th></tr>
  ${items.map(i => `<tr><td>${esc(i.category)}</td><td><b>${esc(i.name)}</b></td><td>${esc(i.purpose || "")}</td><td>${esc(i.version || "")} <code>${esc(JSON.stringify(i.parameters))}</code></td><td>${badge(i.provenance)}<br><span class="muted" style="font-size:11px">${esc(i.provenance_detail)}</span></td><td class="muted">${esc(i.notes)}</td><td><button class="sm ghost" onclick="act(()=>api('/api/projects/${pid}/inventory/${i.id}',{method:'PATCH',body:{provenance:'verified',provenance_detail:prompt('How was this verified?')||''}}),'Marked verified')">mark verified</button> <button class="sm danger" onclick="act(()=>api('/api/projects/${pid}/inventory/${i.id}',{method:'DELETE'}),'Deleted')">×</button></td></tr>`).join("")}</table>
  <h3>Add fact (manual entry)</h3><form onsubmit="return addInv(event,'${pid}')"><div class="grid g4"><div><label>Category</label><select name="category"><option>algorithm</option><option>library</option><option>key_storage</option><option>trust_dependency</option><option>purpose</option><option>process</option><option>platform</option><option>other</option></select></div><div><label>Name</label><input name="name" required></div><div><label>Purpose</label><select name="purpose"><option value="">—</option><option>firmware_signing</option><option>token_signing</option><option>transport_security</option><option>key_establishment</option><option>payload_encryption</option><option>authentication</option></select></div><div><label>Version</label><input name="version"></div>
  <div><label>Parameters (JSON)</label><input name="parameters" value="{}"></div><div><label>Provenance</label><select name="provenance"><option>user_reported</option><option>imported</option><option>verified</option></select></div><div><label>Provenance detail</label><input name="provenance_detail"></div><div><label>Notes</label><input name="notes"></div></div><p><button>Add</button></p></form>
  <h3>Import structured JSON inventory</h3><p class="muted">Format: <code>{"items":[…],"requirements":[…],"platform":{…}}</code> (see <code>seeds/iot_inventory.json</code>). Imported facts are labelled <b>imported</b>; an import cannot assert <i>verified</i>. Repository scanning is a <b>future integration</b> (not implemented).</p>
  <textarea id="invjson" placeholder='{"items": [...]}'></textarea><p><button onclick="act(()=>api('/api/projects/${pid}/inventory/import',{method:'POST',body:JSON.parse($('#invjson').value)}),'Imported')">Import JSON</button></p></div>
  <div class="panel"><h2>Customer-defined limits (acceptance criteria)</h2><table><tr><th>Name</th><th>Metric</th><th>Limit</th><th>Applies to</th><th>Rationale</th><th></th></tr>${reqs.map(r => `<tr><td>${esc(r.name)}</td><td><code>${esc(r.metric)}</code></td><td>${esc(r.operator)} ${r.threshold} ${esc(r.unit)}</td><td>${esc(r.applies_to)}</td><td class="muted">${esc(r.rationale)}</td><td><button class="sm danger" onclick="act(()=>api('/api/projects/${pid}/requirements/${r.id}',{method:'DELETE'}),'Deleted')">×</button></td></tr>`).join("")}</table>
  <form onsubmit="return addReq(event,'${pid}')"><div class="grid g4"><div><label>Name</label><input name="name" required></div><div><label>Metric key</label><input name="metric" placeholder="signature_bytes" required></div><div><label>Operator</label><select name="operator"><option>&lt;=</option><option>&gt;=</option><option>==</option><option>&lt;</option><option>&gt;</option></select></div><div><label>Threshold</label><input name="threshold" type="number" step="any" required></div><div><label>Unit</label><input name="unit"></div><div><label>Applies to</label><select name="applies_to"><option>all</option><option>measured</option><option>imported</option></select></div><div><label>Rationale</label><input name="rationale"></div></div><p><button>Add limit</button></p></form></div>`;
});
window.addInv = (e, pid) => { e.preventDefault(); const b = Object.fromEntries(new FormData(e.target).entries()); try { b.parameters = JSON.parse(b.parameters || "{}"); } catch { return toast("parameters must be JSON", true), false; } if (!b.purpose) delete b.purpose; if (!b.version) delete b.version; act(() => api(`/api/projects/${pid}/inventory`, {method: "POST", body: b}), "Added"); return false; };
window.addReq = (e, pid) => { e.preventDefault(); const b = Object.fromEntries(new FormData(e.target).entries()); b.threshold = parseFloat(b.threshold); act(() => api(`/api/projects/${pid}/requirements`, {method: "POST", body: b}), "Added"); return false; };

// ------------------------------------------------------------------ recommendations
function recBody(b) {
  const sec = (t, c) => `<h3>${t}</h3>${c}`;
  return `${b.observed_problem ? sec("Observed problem", esc(b.observed_problem)) : ""}${b.supporting_evidence ? sec("Supporting evidence (run ids)", nl(b.supporting_evidence)) : ""}${b.proposed_remediation ? sec("Proposed remediation", esc(b.proposed_remediation)) : ""}
  ${sec("What changes", esc(b.what_changes))}${sec("Why", esc(b.why))}${b.security_tradeoff ? `<div class="callout">${esc(b.security_tradeoff)}</div>` : ""}${sec("Relevant threat model", esc(b.threat_model))}${sec("Standards and research references", nl(b.references))}
  ${sec("Library / platform compatibility", `${nl(b.compatibility?.libraries)}<b>Platforms:</b> ${esc((b.compatibility?.platforms || []).join(", "))}${(b.compatibility?.warnings || []).map(w => `<div class="callout bad">⚠ ${esc(w)}</div>`).join("")}`)}
  ${sec("Expected performance trade-offs", nl(b.tradeoffs) + (b.expected_performance_basis ? `<p class="muted">${esc(b.expected_performance_basis)}</p>` : ""))}${b.size_checks?.length ? sec("Catalog size checks against limits", `<table><tr><th>Requirement</th><th>Catalog value</th><th>Limit</th><th></th></tr>${b.size_checks.map(c => `<tr><td>${esc(c.requirement)}</td><td>${c.catalog_value}</td><td>${esc(c.operator)} ${c.threshold}</td><td>${passmark(c.pass)}</td></tr>`).join("")}</table>`) : ""}
  ${sec("Integration requirements", nl(b.integration))}${sec("Evidence still needed", nl(b.evidence_needed))}${sec("What must be retested", nl(b.what_must_be_retested || b.retest_plan))}${b.operational_requirements_hold !== undefined ? sec("Operational requirements still hold (by catalog sizes)", passmark(b.operational_requirements_hold)) : ""}
  ${sec("Known limitations", nl(b.limitations))}${b.alternatives?.length ? sec("Alternatives considered", `<table>${b.alternatives.map(a => `<tr><td>${esc(a.label)}</td><td>${a.warnings.map(w => `<span class="warn">⚠ ${esc(w)}</span>`).join("<br>") || '<span class="muted">no warnings</span>'}</td></tr>`).join("")}</table>`) : ""}`;
}
route(/^\/p\/([^/]+)\/recommendations$/, async (pid) => {
  projNav(pid, "/recommendations");
  const recs = await api(`/api/projects/${pid}/recommendations`);
  return `<h1>Recommendation workspace</h1><p class="sub">Candidates come from a curated catalog of established algorithms and implementation profiles. Purposes are never mixed (a signature scheme is never swapped for a KEM or cipher). Every recommendation needs human review.</p>
  <p><button onclick="act(()=>api('/api/projects/${pid}/recommendations/generate',{method:'POST'}),'Generated from catalog')">Generate from catalog</button></p>
  <div class="panel"><table><tr><th>Title</th><th>Kind</th><th>Purpose</th><th>Generated by</th><th>Human-review status</th><th>Linked</th></tr>
  ${recs.map(r => `<tr class="clickable" onclick="location.hash='#/p/${pid}/recommendations/${r.id}'"><td><b>${esc(r.title)}</b></td><td>${esc(r.kind)}</td><td>${esc(r.purpose || "")}</td><td>${esc(r.generated_by)}</td><td>${badge(r.status)}</td><td>${r.finding_id ? "finding" : ""} ${r.resulting_implementation_id ? "→ implementation" : ""}</td></tr>`).join("") || '<tr><td colspan=6 class="muted">No recommendations yet.</td></tr>'}</table></div>`;
});
route(/^\/p\/([^/]+)\/recommendations\/([^/]+)$/, async (pid, rid) => {
  projNav(pid, "/recommendations");
  const r = await api(`/api/projects/${pid}/recommendations/${rid}`);
  const canImpl = r.status === "approved";
  return `<h1>${esc(r.title)}</h1><p class="sub">${esc(r.kind)} · ${esc(r.purpose || "")} · generated by ${esc(r.generated_by)} · human-review status ${badge(r.status)}</p>
  <div class="grid g2"><div class="panel">${recBody(r.body)}</div>
  <div><div class="panel"><h2>Human review</h2><p class="muted">Reviewer role required. A recommendation never changes production; approval only unlocks creating a new implementation candidate.</p>
  <label>Note</label><input id="recnote"><p class="row"><button onclick="decideRec('${pid}','${rid}','reviewed')">Mark reviewed</button><button onclick="decideRec('${pid}','${rid}','approved')">Approve</button><button class="ghost" onclick="decideRec('${pid}','${rid}','needs_changes')">Needs changes</button><button class="danger" onclick="decideRec('${pid}','${rid}','rejected')">Reject</button></p>
  <h3>Approval history</h3>${r.approvals.length ? `<table>${r.approvals.map(a => `<tr><td>${badge(a.decision)}</td><td>${esc(a.note)}</td><td class="muted">${when(a.created_at)}</td></tr>`).join("")}</table>` : '<p class="muted">None yet.</p>'}</div>
  ${r.finding ? `<div class="panel"><h2>Linked finding</h2><a href="#/p/${pid}/findings/${r.finding.id}">${esc(r.finding.title)}</a> ${badge(r.finding.status)}</div>` : ""}
  ${r.target_implementation ? `<div class="panel"><h2>Affected implementation</h2><a href="#/p/${pid}/implementations/${r.target_implementation.id}">${esc(r.target_implementation.name)} ${esc(r.target_implementation.version)}</a> ${badge(r.target_implementation.status)}</div>` : ""}
  ${r.resulting_implementation ? `<div class="panel"><h2>Resulting implementation</h2><a href="#/p/${pid}/implementations/${r.resulting_implementation.id}">${esc(r.resulting_implementation.name)} ${esc(r.resulting_implementation.version)}</a> ${badge(r.resulting_implementation.status)}</div>` :
  `<div class="panel"><h2>Create implementation candidate</h2>${canImpl ? "" : '<p class="callout">Available once the recommendation is <b>approved</b>.</p>'}<form onsubmit="return implementRec(event,'${pid}','${rid}')"><div class="grid g2"><div><label>Name</label><input name="name" value="${esc(r.target_implementation?.name || "")}" required></div><div><label>Version</label><input name="version" placeholder="3.0.0-rc2" required></div><div><label>Source revision</label><input name="source_revision" placeholder="git sha / tag"></div><div><label>Library</label><input name="library" value="${esc((r.profile?.libraries || [])[0] || "")}"></div><div><label>Library version</label><input name="library_version"></div><div><label>Delivery mode</label><select name="delivery_mode"><option value="">—</option><option>remote</option><option>customer_lab</option><option>isogeny_lab</option><option>onsite</option><option>container</option></select></div></div><label>Target environment (JSON)</label><input name="target_environment" value='${esc(JSON.stringify(r.target_implementation?.target_environment || {}))}'><label>Notes</label><input name="notes"><p><button ${canImpl ? "" : "disabled"}>Create candidate</button></p></form></div>`}
  </div></div>`;
});
window.decideRec = (pid, rid, d) => act(() => api(`/api/projects/${pid}/recommendations/${rid}/decide`, {method: "POST", body: {decision: d, note: $("#recnote").value}}), "Decision recorded");
window.implementRec = (e, pid, rid) => { e.preventDefault(); const b = Object.fromEntries(new FormData(e.target).entries()); try { b.target_environment = JSON.parse(b.target_environment || "{}"); } catch { return toast("target_environment must be JSON", true), false; } if (!b.delivery_mode) delete b.delivery_mode; act(async () => { const i = await api(`/api/projects/${pid}/recommendations/${rid}/implement`, {method: "POST", body: b}); location.hash = `#/p/${pid}/implementations/${i.id}`; }, "Candidate created"); return false; };

// ------------------------------------------------------------------ implementations
route(/^\/p\/([^/]+)\/implementations$/, async (pid) => {
  projNav(pid, "/implementations");
  const [impls, cat, p] = await Promise.all([api(`/api/projects/${pid}/implementations`), api("/api/catalog"), api(`/api/projects/${pid}`)]);
  return `<h1>Implementation workspace</h1><p class="sub">Each implementation is a versioned candidate tied to an exact source revision, configuration and target environment. This platform produces proposed-change records; it never deploys customer changes.</p>
  <div class="panel"><table><tr><th>Name / version</th><th>Role</th><th>Status</th><th>Algorithm · library</th><th>Source revision</th><th>Delivery</th><th>Runs</th><th>Latest</th><th>Warnings</th></tr>
  ${impls.map(i => `<tr class="clickable" onclick="location.hash='#/p/${pid}/implementations/${i.id}'"><td><b>${esc(i.name)} ${esc(i.version)}</b></td><td>${badge(i.role)}</td><td>${badge(i.status)}</td><td>${esc(i.algorithm)}<br><span class="muted">${esc(i.library)} ${esc(i.library_version)}</span></td><td><code>${esc(i.source_revision)}</code></td><td>${esc(i.delivery_mode || "")}</td><td>${i.run_count}</td><td>${passmark(i.latest_pass)}</td><td>${i.compatibility_warnings.length ? `<span class="warn">⚠ ${i.compatibility_warnings.length}</span>` : ""}</td></tr>`).join("")}</table></div>
  <div class="panel"><h2>Record baseline or candidate</h2><form onsubmit="return newImpl(event,'${pid}')"><div class="grid g4"><div><label>Name</label><input name="name" required></div><div><label>Version</label><input name="version" required></div><div><label>Role</label><select name="role"><option>candidate</option><option>baseline</option></select></div><div><label>Catalog profile</label><select name="profile_id"><option value="">— (free text algorithm)</option>${cat.profiles.map(pr => `<option value="${pr.id}">${esc(pr.label)} [${pr.purpose}]</option>`).join("")}</select></div>
  <div><label>Algorithm (if no profile)</label><input name="algorithm"></div><div><label>Library</label><input name="library"></div><div><label>Library version</label><input name="library_version"></div><div><label>Source revision</label><input name="source_revision"></div>
  <div><label>Delivery mode</label><select name="delivery_mode"><option value="">—</option>${p.kind === "iot" ? "<option>remote</option><option>customer_lab</option><option>isogeny_lab</option><option>onsite</option>" : "<option>container</option><option>remote</option>"}</select></div><div><label>Parent (replaces) id</label><input name="parent_id"></div></div>
  <div class="grid g3"><div><label>Configuration (JSON; fixture_params override fixture inputs)</label><input name="configuration" value="{}"></div><div><label>Target environment (JSON: board/mcu or image/cpu)</label><input name="target_environment" value="{}"></div><div><label>Build identity (JSON: dependencies, image digest, toolchain)</label><input name="build_identity" value="{}"></div></div><label>Notes</label><input name="notes"><p><button>Record implementation</button></p></form></div>`;
});
window.newImpl = (e, pid) => { e.preventDefault(); const b = Object.fromEntries(new FormData(e.target).entries()); for (const k of ["configuration", "target_environment", "build_identity"]) { try { b[k] = JSON.parse(b[k] || "{}"); } catch { return toast(k + " must be JSON", true), false; } } for (const k of ["profile_id", "delivery_mode", "parent_id"]) if (!b[k]) delete b[k]; act(async () => { const i = await api(`/api/projects/${pid}/implementations`, {method: "POST", body: b}); location.hash = `#/p/${pid}/implementations/${i.id}`; }, "Recorded"); return false; };

route(/^\/p\/([^/]+)\/implementations\/([^/]+)$/, async (pid, iid) => {
  projNav(pid, "/implementations");
  const [i, exps, runners, p] = await Promise.all([api(`/api/projects/${pid}/implementations/${iid}`), api(`/api/projects/${pid}/experiments`), api("/api/runners"), api(`/api/projects/${pid}`)]);
  const fixtureExps = exps.filter(e => e.fixture !== "external"), importExps = exps;
  return `<h1>${esc(i.name)} ${esc(i.version)} ${badge(i.role)} ${badge(i.status)}</h1><p class="sub">${esc(i.algorithm)} · ${esc(i.library)} ${esc(i.library_version)} · revision <code>${esc(i.source_revision || "—")}</code> · delivery ${esc(i.delivery_mode || "—")}</p>
  ${i.compatibility_warnings.map(w => `<div class="callout bad">⚠ ${esc(w)}</div>`).join("")}
  <div class="grid g2"><div>
  <div class="panel"><h2>Identity</h2><dl class="kv"><dt>Configuration</dt><dd><code>${esc(JSON.stringify(i.configuration))}</code></dd><dt>Target environment</dt><dd><code>${esc(JSON.stringify(i.target_environment))}</code></dd><dt>Build identity</dt><dd><code>${esc(JSON.stringify(i.build_identity))}</code></dd><dt>Catalog profile</dt><dd>${i.profile ? `${esc(i.profile.label)} — ${esc(i.profile.standards.join("; "))}` : "—"}</dd><dt>Replaces</dt><dd>${i.parent_id ? `<a href="#/p/${pid}/implementations/${i.parent_id}">parent</a>` : "—"}</dd><dt>From recommendation</dt><dd>${i.recommendation_id ? `<a href="#/p/${pid}/recommendations/${i.recommendation_id}">recommendation</a>` : "—"}</dd><dt>Notes</dt><dd>${esc(i.notes)}</dd></dl>
  ${i.profile && !i.profile.fixture ? '<div class="callout">No fixture exists for this profile; evidence must be imported.</div>' : ""}</div>
  <div class="panel"><h2>Status &amp; approvals</h2><div class="flow">${["draft", "proposed", "approved", "superseded"].map(s => `<span class="${s === i.status ? "cur" : ""}">${s}</span>`).join("")}</div>
  <p class="row">${i.status === "draft" ? `<button onclick="act(()=>api('/api/projects/${pid}/implementations/${iid}/propose',{method:'POST'}),'Proposed for review')">Propose for review</button>` : ""}
  ${["proposed", "draft"].includes(i.status) ? `<input id="implnote" placeholder="review note" style="max-width:260px"><button onclick="act(()=>api('/api/projects/${pid}/implementations/${iid}/decide',{method:'POST',body:{decision:'approved',note:$('#implnote').value}}),'Approved')">Approve (reviewer)</button><button class="danger" onclick="act(()=>api('/api/projects/${pid}/implementations/${iid}/decide',{method:'POST',body:{decision:'rejected',note:$('#implnote').value}}),'Rejected')">Reject</button>` : ""}</p>
  <table>${i.approvals.map(a => `<tr><td>${badge(a.decision)}</td><td>${esc(a.note)}</td><td class="muted">${when(a.created_at)}</td></tr>`).join("") || '<tr><td class="muted">No approval records.</td></tr>'}</table>
  <h3>Proposed change record</h3><p class="muted">A downloadable change/configuration artifact. Deployment is <b>not</b> performed by this platform.</p>${i.change_artifact ? `<p><a href="#" onclick="return dl(event,'/api/projects/${pid}/artifacts/${i.change_artifact.id}/download','change.json')">${esc(i.change_artifact.filename)}</a> <code>sha256 ${esc(i.change_artifact.sha256.slice(0, 16))}…</code></p>` : ""}<button class="ghost sm" onclick="act(()=>api('/api/projects/${pid}/implementations/${iid}/change-artifact',{method:'POST'}),'Change record created')">Generate change record</button></div>
  <div class="panel"><h2>Tasks</h2><table>${i.tasks.map(t => `<tr><td>${esc(t.title)}</td><td class="muted">${esc(t.owner)}</td><td><select onchange="act(()=>api('/api/projects/${pid}/implementations/${iid}/tasks/${t.id}',{method:'PATCH',body:{status:this.value}}),'Task updated')">${["open", "in_progress", "blocked", "done"].map(s => `<option ${s === t.status ? "selected" : ""}>${s}</option>`).join("")}</select></td></tr>`).join("")}</table>
  <form onsubmit="return addTask(event,'${pid}','${iid}')" class="row"><input name="title" placeholder="task title" required style="flex:2"><input name="owner" placeholder="owner" style="flex:1"><button class="sm">Add</button></form></div>
  </div><div>
  <div class="panel"><h2>Run fixture (measured)</h2><p class="muted">Executes the experiment's fixture against this implementation in an isolated runner. Host-side measurements; device numbers must be imported.</p>
  <label>Experiment</label><select id="runexp">${fixtureExps.map(e => `<option value="${e.id}">${esc(e.name)} [${e.fixture}]</option>`).join("")}</select>
  <label>Runner</label><select id="runner">${runners.filter(r => r.kind !== "import" && r.kind !== "hardware").map(r => `<option value="${r.kind}" ${r.available ? "" : "disabled"}>${r.kind} ${r.available ? "" : "(unavailable: " + esc(r.unavailable_reason) + ")"}${r.tested_in_this_environment ? "" : " — untested here"}</option>`).join("")}</select>
  <label>Correction of run id (optional; creates a NEW record that supersedes it)</label><input id="supersedes" placeholder="run id"><label>Correction note</label><input id="corrnote"><p><button ${fixtureExps.length ? "" : "disabled"} onclick="act(()=>api('/api/projects/${pid}/runs',{method:'POST',body:{experiment_id:$('#runexp').value,implementation_id:'${iid}',runner_kind:$('#runner').value,supersedes_run_id:$('#supersedes').value||null,correction_note:$('#corrnote').value}}),'Run queued — see Evidence')">Queue run</button></p></div>
  <div class="panel"><h2>Import external results (imported)</h2><p class="muted">Device-lab, customer-lab, onsite or hardware agent output following the result schema (<code>docs/RUNNER_INTERFACE.md</code>). The platform checks schema and records the hash; it does not vouch for the measurement.</p>
  <label>Experiment</label><select id="impexp">${importExps.map(e => `<option value="${e.id}">${esc(e.name)} [${e.fixture}]</option>`).join("")}</select><label>Result document (JSON)</label><textarea id="impdoc" placeholder='{"fixture":"firmware_signing","fixture_version":"lab/1","status":"completed","metrics":{...},"scenarios":[...],"environment":{"board":"...","measured_by":"..."}}'></textarea>
  <label><input type="checkbox" id="illus" style="width:auto"> This is illustrative / demonstration data (not a real measurement)</label><p><button onclick="act(()=>api('/api/projects/${pid}/runs/import',{method:'POST',body:{experiment_id:$('#impexp').value,implementation_id:'${iid}',document:JSON.parse($('#impdoc').value),illustrative:$('#illus').checked}}),'Imported')">Import</button></p></div>
  <div class="panel"><h2>Evidence for this implementation</h2><table><tr><th>#</th><th>Status</th><th>Provenance</th><th>Result</th><th>Failed requirements</th></tr>${i.runs.map(r => `<tr class="clickable" onclick="location.hash='#/p/${pid}/runs/${r.id}'"><td>${r.sequence}</td><td>${badge(r.status)}</td><td>${prov(r.provenance)}</td><td>${passmark(r.overall_pass)}</td><td class="bad" style="font-size:12px">${esc(r.requirement_results.filter(x => x.pass === false).map(x => x.name).join(", "))}</td></tr>`).join("") || '<tr><td colspan=5 class="muted">No evidence yet.</td></tr>'}</table></div>
  ${i.children.length ? `<div class="panel"><h2>Superseded by / child versions</h2>${i.children.map(c => `<a href="#/p/${pid}/implementations/${c.id}">${esc(c.name)} ${esc(c.version)}</a> ${badge(c.status)}<br>`).join("")}</div>` : ""}
  </div></div>`;
});
window.addTask = (e, pid, iid) => { e.preventDefault(); const b = Object.fromEntries(new FormData(e.target).entries()); act(() => api(`/api/projects/${pid}/implementations/${iid}/tasks`, {method: "POST", body: b}), "Task added"); return false; };

// ------------------------------------------------------------------ evidence (runs)
route(/^\/p\/([^/]+)\/runs$/, async (pid) => {
  projNav(pid, "/runs");
  const [runs, exps] = await Promise.all([api(`/api/projects/${pid}/runs`), api(`/api/projects/${pid}/experiments`)]);
  return `<h1>Evidence lab — run records</h1><p class="sub">Append-only. Corrections create new records that reference the superseded run. Provenance is shown on every record.</p>
  <div class="panel"><table><tr><th>#</th><th>Experiment</th><th>Implementation</th><th>Runner</th><th>Provenance</th><th>Status</th><th>Result</th><th>Failed requirements / scenarios</th><th>Supersedes</th><th>When</th></tr>
  ${runs.slice().reverse().map(r => `<tr class="clickable" onclick="location.hash='#/p/${pid}/runs/${r.id}'"><td>${r.sequence}</td><td>${esc(r.experiment_name)}</td><td>${esc(r.implementation_label)}</td><td>${esc(r.runner_kind)} <span class="muted">${esc(r.runner_version)}</span></td><td>${prov(r.provenance)}</td><td>${badge(r.status)}</td><td>${passmark(r.overall_pass)}</td><td class="bad" style="font-size:12px">${esc([...r.requirement_results.filter(x => x.pass === false).map(x => x.name), ...r.scenarios.filter(s => s.pass === false).map(s => s.id)].join(", "))}</td><td>${r.supersedes_run_id ? "yes" : ""}</td><td class="muted">${when(r.created_at)}</td></tr>`).join("")}</table></div>
  <div class="panel"><h2>Experiments (definitions &amp; acceptance criteria)</h2><table><tr><th>Name</th><th>Fixture</th><th>Definition</th><th>Acceptance criteria</th></tr>${exps.map(e => `<tr><td><b>${esc(e.name)}</b><br><span class="muted">${esc(e.description)}</span></td><td><code>${esc(e.fixture)}</code></td><td><code>${esc(JSON.stringify(e.definition))}</code></td><td>${nl(e.acceptance_criteria)}</td></tr>`).join("")}</table>
  <h3>New experiment</h3><form onsubmit="return newExp(event,'${pid}')"><div class="grid g3"><div><label>Name</label><input name="name" required></div><div><label>Fixture</label><select name="fixture"><option>firmware_signing</option><option>app_service_crypto</option><option>toy_factoring</option><option value="external">external (import only)</option></select></div><div><label>Definition (JSON, e.g. {"params":{"repeat_count":50}})</label><input name="definition" value='{"params": {}}'></div></div><label>Description</label><input name="description"><p><button>Create</button></p></form></div>`;
});
window.newExp = (e, pid) => { e.preventDefault(); const b = Object.fromEntries(new FormData(e.target).entries()); try { b.definition = JSON.parse(b.definition); } catch { return toast("definition must be JSON", true), false; } act(() => api(`/api/projects/${pid}/experiments`, {method: "POST", body: b}), "Experiment created"); return false; };

route(/^\/p\/([^/]+)\/runs\/([^/]+)$/, async (pid, rid) => {
  projNav(pid, "/runs");
  const r = await api(`/api/projects/${pid}/runs/${rid}`);
  const mdef = (k) => r.metric_definitions[k] || Object.entries(r.metric_definitions).find(([kk]) => kk.endsWith("*") && k.startsWith(kk.slice(0, -1)))?.[1] || "";
  return `<h1>Run #${r.sequence} ${badge(r.status)} ${prov(r.provenance)} ${passmark(r.overall_pass)}</h1><p class="sub">${esc(r.experiment.name)} · ${esc(r.implementation.name)} ${esc(r.implementation.version)} · runner ${esc(r.runner_kind)} ${esc(r.runner_version)} · fixture ${esc(r.fixture_version)} · ${when(r.created_at)}</p>
  ${r.provenance === "illustrative" ? '<div class="callout">ILLUSTRATIVE DATA — demonstration numbers, not a measurement.</div>' : r.provenance === "imported" ? '<div class="callout info">Imported evidence — measured outside this platform; schema and hash verified only.</div>' : ""}
  ${r.supersedes_run_id ? `<div class="callout info">Correction of <a href="#/p/${pid}/runs/${r.supersedes_run_id}">an earlier run</a>: ${esc(r.correction_note)}</div>` : ""}${r.superseded_by.length ? `<div class="callout">Superseded by ${r.superseded_by.map(s => `<a href="#/p/${pid}/runs/${s.id}">run #${s.sequence}</a>`).join(", ")} (this record is kept unchanged).</div>` : ""}
  ${r.failures.length ? `<div class="callout bad"><b>Failures</b>${nl(r.failures)}</div>` : ""}
  <div class="grid g2"><div>
  <div class="panel"><h2>Requirement evaluation</h2><table><tr><th>Requirement</th><th>Limit</th><th>Observed</th><th></th></tr>${r.requirement_results.map(x => `<tr><td>${esc(x.name)}</td><td><code>${esc(x.metric)} ${esc(x.operator)} ${x.threshold} ${esc(x.unit)}</code></td><td>${fmt(x.observed)}</td><td>${passmark(x.pass)} <span class="muted">${esc(x.note || "")}</span></td></tr>`).join("")}</table></div>
  <div class="panel"><h2>Scenarios (functional correctness &amp; rejection of invalid inputs)</h2><table><tr><th>Scenario</th><th>Expected</th><th>Observed</th><th></th></tr>${r.scenarios.map(s => `<tr><td>${esc(s.name || s.id)}<br><span class="muted">${esc(s.detail || "")}</span></td><td>${esc(s.expected)}</td><td>${esc(s.observed)}</td><td>${passmark(s.pass)}</td></tr>`).join("")}</table><p class="muted">Passing these scenarios shows the verifier rejected these specific malformed inputs. It is not proof of security.</p></div>
  <div class="panel"><h2>Metrics (with measurement definitions)</h2><table><tr><th>Metric</th><th>Value</th><th>Definition</th></tr>${Object.entries(r.metrics).map(([k, v]) => `<tr><td><code>${esc(k)}</code></td><td>${fmt(v)}</td><td class="muted" style="font-size:12px">${esc(mdef(k))}</td></tr>`).join("")}</table></div>
  </div><div>
  <div class="panel"><h2>Provenance &amp; reproducibility</h2><dl class="kv"><dt>Repeat count</dt><dd>${r.repeat_count}</dd><dt>Environment</dt><dd>${json(r.environment)}</dd><dt>Commands / configuration</dt><dd>${json(r.commands)}</dd><dt>Artifact hashes</dt><dd><code>${esc(JSON.stringify(r.artifact_hashes))}</code> ${r.raw_artifact ? (r.raw_artifact_integrity_ok ? '<span class="ok">integrity ok</span>' : '<span class="bad">INTEGRITY MISMATCH</span>') : ""}</dd><dt>Raw output</dt><dd>${r.raw_artifact ? `<a href="#" onclick="return dl(event,'/api/projects/${pid}/artifacts/${r.raw_artifact.id}/download','raw.json')">${esc(r.raw_artifact.filename)}</a> (${r.raw_artifact.size} B)` : "—"}</dd><dt>Job</dt><dd>${r.job ? `${badge(r.job.status)} ${esc(r.job.error || "")}` : "—"}</dd></dl></div>
  <div class="panel"><h2>Limitations &amp; exclusions</h2>${nl(r.limitations)}${r.exclusions.length ? `<h3>Exclusions</h3>${nl(r.exclusions)}` : ""}</div>
  <div class="panel"><h2>Raw output (first-class evidence)</h2>${r.raw ? `<details><summary>Show raw JSON</summary>${json(r.raw)}</details>` : '<p class="muted">none</p>'}</div>
  </div></div>`;
});

// ------------------------------------------------------------------ compare
route(/^\/p\/([^/]+)\/compare$/, async (pid, q) => {
  projNav(pid, "/compare");
  const runs = (await api(`/api/projects/${pid}/runs`)).filter(r => r.status === "completed");
  const opts = (sel) => runs.map(r => `<option value="${r.id}" ${r.id === sel ? "selected" : ""}>#${r.sequence} ${esc(r.implementation_label)} — ${esc(r.experiment_name)} [${r.provenance}]</option>`).join("");
  let body = "";
  if (q.b && q.c) {
    const c = await api(`/api/projects/${pid}/compare?baseline_run_id=${q.b}&candidate_run_id=${q.c}`);
    body = `<div class="callout ${c.comparable ? "info" : ""}">${esc(c.comparability_note)}</div>
    <div class="grid g2"><div class="panel"><h3>Baseline: run #${c.baseline.sequence} ${prov(c.baseline.provenance)}</h3>${esc(c.baseline.implementation.name)} ${esc(c.baseline.implementation.version)} — ${esc(c.baseline.implementation.algorithm)} ${passmark(c.baseline.overall_pass)}</div><div class="panel"><h3>Candidate: run #${c.candidate.sequence} ${prov(c.candidate.provenance)}</h3>${esc(c.candidate.implementation.name)} ${esc(c.candidate.implementation.version)} — ${esc(c.candidate.implementation.algorithm)} ${passmark(c.candidate.overall_pass)}</div></div>
    <div class="panel"><h2>Metrics</h2><table><tr><th>Metric</th><th>Baseline</th><th>Candidate</th><th>Δ</th><th>Δ %</th><th>Definition</th></tr>${c.metrics.map(m => `<tr><td><code>${esc(m.metric)}</code></td><td>${fmt(m.baseline)}</td><td>${fmt(m.candidate)}</td><td>${fmt(m.delta)}</td><td>${m.delta_pct === null || m.delta_pct === undefined ? "—" : m.delta_pct.toFixed(1) + "%"}</td><td class="muted" style="font-size:12px">${esc(m.definition)}</td></tr>`).join("")}</table></div>
    <div class="grid g2"><div class="panel"><h2>Requirements</h2><table><tr><th>Requirement</th><th>Baseline</th><th>Candidate</th></tr>${c.requirements.candidate.map((x, i) => `<tr><td>${esc(x.name)}</td><td>${fmt(c.requirements.baseline[i]?.observed)} ${passmark(c.requirements.baseline[i]?.pass)}</td><td>${fmt(x.observed)} ${passmark(x.pass)}</td></tr>`).join("")}</table></div>
    <div class="panel"><h2>Scenarios</h2><table><tr><th>Scenario</th><th>Baseline</th><th>Candidate</th></tr>${c.scenarios.map(s => `<tr><td>${esc(s.id)}</td><td>${passmark(s.baseline)}</td><td>${passmark(s.candidate)}</td></tr>`).join("")}</table></div></div>`;
  }
  return `<h1>Baseline versus candidate</h1><p class="sub">Compare two completed runs. Only runs with the same provenance and runner are numerically comparable; otherwise compare requirement outcomes.</p>
  <div class="panel row"><div style="flex:1"><label>Baseline run</label><select id="cb">${opts(q.b)}</select></div><div style="flex:1"><label>Candidate run</label><select id="cc">${opts(q.c)}</select></div><button onclick="location.hash='#/p/${pid}/compare?b='+$('#cb').value+'&c='+$('#cc').value">Compare</button></div>${body}`;
});

// ------------------------------------------------------------------ research inbox & findings
const FLOW = ["new", "triage", "relevant", "experiment_proposed", "reviewed", "action_approved", "retested", "closed"];
route(/^\/p\/([^/]+)\/research$/, async (pid) => {
  projNav(pid, "/research");
  const [findings, sources, st] = await Promise.all([api(`/api/projects/${pid}/findings`), api(`/api/projects/${pid}/research/sources`), api(`/api/projects/${pid}/research/status`)]);
  return `<h1>Research inbox</h1><p class="sub">Auto-researcher: submit URLs or documents, trigger a review, triage findings. Retrieved documents are untrusted data — nothing in them is executed or followed. Human review is required before any finding changes a production recommendation.</p>
  <div class="callout info">Extraction mode: <b>${esc(st.extraction_method)}</b>. ${esc(st.note)} Scheduled monitoring is a future use of this same interface (not implemented).</div>
  <div class="grid g2"><div class="panel"><h2>Findings</h2><table><tr><th>Title</th><th>Origin</th><th>Status</th><th>Reproduction</th><th>Follow-up</th></tr>${findings.map(f => `<tr class="clickable" onclick="location.hash='#/p/${pid}/findings/${f.id}'"><td><b>${esc(f.title)}</b> ${demo(f.is_demo)}<br><span class="muted" style="font-size:12px">${esc((f.summary || "").slice(0, 140))}</span></td><td>${esc(f.origin)}<br><span class="muted" style="font-size:11px">${esc(f.extraction_method)}</span></td><td>${badge(f.status)}</td><td style="font-size:12px">${esc([...new Set((f.claims || []).map(c => c.reproduced))].join(", ") || "—")}</td><td style="font-size:12px">${esc(f.proposed_followup?.type || "")}</td></tr>`).join("") || '<tr><td colspan=5 class="muted">No findings.</td></tr>'}</table></div>
  <div><div class="panel"><h2>Submit research source</h2><form onsubmit="return submitSrc(event,'${pid}')"><label>Title</label><input name="title"><label>URL (fetched server-side as untrusted text) — or paste the document below</label><input name="url" placeholder="https://…"><label>Document text</label><textarea name="content"></textarea><label><input type="checkbox" name="is_demo" style="width:auto"> Label as demonstration</label><p><button>Submit &amp; review</button></p></form></div>
  <div class="panel"><h2>Sources</h2><table>${sources.map(s => `<tr><td>${esc(s.title)} ${demo(s.is_demo)}<br><span class="muted" style="font-size:11px">${esc(s.source_type)} · sha256 ${esc(s.content_sha256.slice(0, 12))}… · ${esc(s.extraction_method)}</span></td><td>${badge(s.review_status)}</td><td><button class="sm ghost" onclick="act(()=>api('/api/projects/${pid}/research/sources/${s.id}/review?wait=true',{method:'POST'}),'Re-reviewed')">re-review</button></td></tr>`).join("") || '<tr><td class="muted">None.</td></tr>'}</table></div>
  <div class="panel"><h2>Manual finding</h2><form onsubmit="return manualFinding(event,'${pid}')"><label>Title</label><input name="title" required><label>Summary</label><input name="summary"><p><button class="ghost">Add finding</button></p></form></div></div></div>`;
});
window.submitSrc = (e, pid) => { e.preventDefault(); const b = Object.fromEntries(new FormData(e.target).entries()); b.is_demo = !!b.is_demo; b.wait = true; if (!b.url) delete b.url; if (!b.content) delete b.content; act(() => api(`/api/projects/${pid}/research/sources`, {method: "POST", body: b}), "Source reviewed; finding created"); return false; };
window.manualFinding = (e, pid) => { e.preventDefault(); const b = Object.fromEntries(new FormData(e.target).entries()); act(() => api(`/api/projects/${pid}/findings`, {method: "POST", body: b}), "Finding added"); return false; };

route(/^\/p\/([^/]+)\/findings\/([^/]+)$/, async (pid, fid) => {
  projNav(pid, "/research");
  const [f, runs] = await Promise.all([api(`/api/projects/${pid}/findings/${fid}`), api(`/api/projects/${pid}/runs`)]);
  const idx = FLOW.indexOf(f.status);
  const next = {new: ["triage", "not_relevant"], triage: ["relevant", "experiment_proposed", "not_relevant"], relevant: ["experiment_proposed", "reviewed", "not_relevant"], experiment_proposed: ["reviewed", "relevant"], reviewed: ["action_approved", "closed", "relevant"], action_approved: [], retested: ["closed", "reviewed"], closed: ["relevant"], not_relevant: ["triage"]}[f.status] || [];
  const completed = runs.filter(r => r.status === "completed");
  return `<h1>${esc(f.title)} ${demo(f.is_demo)}</h1><p class="sub">${esc(f.origin)} finding · extraction ${esc(f.extraction_method)} · ${when(f.created_at)}</p>
  <div class="flow">${FLOW.map((s, i) => `<span class="${s === f.status ? "cur" : i < idx ? "done" : ""}">${s.replace(/_/g, " ")}</span>`).join("")}${f.status === "not_relevant" ? '<span class="cur">not relevant</span>' : ""}</div>
  <div class="grid g2" style="margin-top:12px"><div>
  <div class="panel"><h2>Finding</h2><p>${esc(f.summary)}</p><h3>Source-backed claims</h3>${f.claims.length ? `<table><tr><th>Claim</th><th>Status</th></tr>${f.claims.map(c => `<tr><td>${esc(c.text)}${c.quote && c.quote !== c.text ? `<br><i class="muted">“${esc(c.quote)}”</i>` : ""}</td><td>${badge(c.reproduced)}</td></tr>`).join("")}</table>` : '<p class="muted">No extracted claims.</p>'}<p class="muted" style="font-size:12px"><b>published</b> = claim as stated by the source · <b>independently reproduced</b> = source reports an independent reproduction · <b>internal measurement</b> = produced by this platform's runs.</p>
  <h3>Affected algorithms / libraries / versions / platforms</h3>${json(f.affected)}<h3>Relevance to this project</h3><p>${esc(f.relevance)}</p><h3>Uncertainty</h3><p>${esc(f.uncertainty)}</p>
  <h3>Matched inventory</h3>${f.matched_inventory_ids.length ? `${f.matched_inventory_ids.length} inventory item(s) — <a href="#/p/${pid}/inventory">view inventory</a>` : '<span class="muted">none</span>'}<h3>Affected implementations</h3>${f.affected_implementations.map(i => `<a href="#/p/${pid}/implementations/${i.id}">${esc(i.name)} ${esc(i.version)}</a> ${badge(i.status)}<br>`).join("") || '<span class="muted">none</span>'}
  <h3>Proposed follow-up</h3><p>${badge(f.proposed_followup?.type || "none")} ${esc(f.proposed_followup?.description || "")}</p>${f.source ? `<h3>Source</h3><p>${esc(f.source.title)} ${f.source.url ? `<a href="${esc(f.source.url)}" rel="noopener" target="_blank">link</a>` : ""} <code>sha256 ${esc(f.source.content_sha256.slice(0, 16))}…</code> ${demo(f.source.is_demo)}</p><details><summary>Show stored document (untrusted data)</summary><pre>${esc(f.source.content)}</pre></details>` : ""}</div>
  <div class="panel"><h2>Status history</h2><table>${f.status_history.map(h => `<tr><td>${badge(h.status)}</td><td>${esc(h.note || "")}</td><td class="muted">${esc(h.by || "")} ${h.at ? when(h.at) : ""}</td></tr>`).join("")}</table></div>
  </div><div>
  <div class="panel"><h2>Assisted remediation</h2><p class="muted">Finding → affected implementation → proposed change → human approval → new implementation version → rerun tests → compare evidence → close or reopen.</p>
  ${f.recommendation ? `<p>Recommendation: <a href="#/p/${pid}/recommendations/${f.recommendation.id}">${esc(f.recommendation.title)}</a> ${badge(f.recommendation.status)}</p>` : `<button onclick="act(()=>api('/api/projects/${pid}/recommendations/from-finding/${fid}',{method:'POST'}),'Remediation proposal drafted')">Generate remediation proposal</button>`}
  <h3>Change status (human)</h3><label>Note</label><input id="fnote"><p class="row">${next.map(s => `<button class="${s === "not_relevant" ? "danger" : s === "closed" ? "" : "ghost"}" onclick="act(()=>api('/api/projects/${pid}/findings/${fid}/status',{method:'POST',body:{status:'${s}',note:$('#fnote').value}}),'Status updated')">${s.replace(/_/g, " ")}</button>`).join("") || '<span class="muted">No manual transitions from this state (use retest / resolve below).</span>'}</p>
  <h3>Record retest</h3><p class="muted">Link a new run of the remediated candidate. A failed retest keeps the finding open.</p><select id="retestrun">${completed.map(r => `<option value="${r.id}">#${r.sequence} ${esc(r.implementation_label)} [${r.provenance}] ${r.overall_pass ? "pass" : "FAIL"}</option>`).join("")}</select><p><button ${f.status === "action_approved" ? "" : "disabled"} onclick="act(()=>api('/api/projects/${pid}/findings/${fid}/retest',{method:'POST',body:{run_id:$('#retestrun').value}}),'Retest recorded')">Record retest</button> ${f.status !== "action_approved" ? '<span class="muted">(needs status action_approved)</span>' : ""}</p>
  <h3>Compare evidence and resolve</h3><label>Baseline run</label><select id="resb">${completed.map(r => `<option value="${r.id}">#${r.sequence} ${esc(r.implementation_label)} [${r.provenance}]</option>`).join("")}</select><label>Candidate (retest) run</label><select id="resc">${completed.map(r => `<option value="${r.id}">#${r.sequence} ${esc(r.implementation_label)} [${r.provenance}] ${r.overall_pass ? "pass" : "FAIL"}</option>`).join("")}</select>
  <p class="row"><button class="ghost" onclick="location.hash='#/p/${pid}/compare?b='+$('#resb').value+'&c='+$('#resc').value">Open comparison</button><button onclick="act(()=>api('/api/projects/${pid}/findings/${fid}/resolve',{method:'POST',body:{baseline_run_id:$('#resb').value,candidate_run_id:$('#resc').value,decision:'close',note:$('#fnote').value}}),'Finding closed')">Close (requires passing candidate)</button><button class="danger" onclick="act(()=>api('/api/projects/${pid}/findings/${fid}/resolve',{method:'POST',body:{candidate_run_id:$('#resc').value,decision:'reopen',note:$('#fnote').value}}),'Finding reopened')">Reopen</button></p></div>
  <div class="panel"><h2>Evidence runs linked</h2><table>${f.evidence_runs.map(r => `<tr class="clickable" onclick="location.hash='#/p/${pid}/runs/${r.id}'"><td>#${r.sequence}</td><td>${prov(r.provenance)}</td><td>${passmark(r.overall_pass)}</td><td class="muted">${when(r.created_at)}</td></tr>`).join("") || '<tr><td class="muted">None linked.</td></tr>'}</table></div>
  </div></div>`;
});

// ------------------------------------------------------------------ attack cost
route(/^\/p\/([^/]+)\/attack$/, async (pid) => {
  projNav(pid, "/attack");
  const [a, runs] = await Promise.all([api(`/api/projects/${pid}/attack-assessments`), api(`/api/projects/${pid}/runs`)]);
  const toyRuns = runs.filter(r => r.status === "completed" && r.metrics.iterations_per_second);
  const card = (x) => `<div class="panel"><div class="row"><b>${esc(x.target)}</b> ${badge(x.category)} ${badge(x.attack_model)} ${demo(x.is_demo)}</div>
  <dl class="kv"><dt>Parameters</dt><dd><code>${esc(JSON.stringify(x.target_parameters))}</code></dd><dt>Objective</dt><dd>${esc(x.objective)}</dd><dt>Attacker capabilities</dt><dd>${esc(x.attacker_capabilities)}</dd><dt>Method &amp; source</dt><dd>${esc(x.method)}<br><span class="muted">${esc(x.source)}</span></dd><dt>Hardware assumptions</dt><dd>${esc(x.hardware_assumptions)}</dd>
  <dt>Measured throughput</dt><dd>${x.measured_throughput ? `${fmt(x.measured_throughput.value)} ${esc(x.measured_throughput.unit)} ${x.measured_throughput.run_id ? `(<a href="#/p/${pid}/runs/${x.measured_throughput.run_id}">run</a>)` : ""}` : '<span class="na">none</span>'}</dd>
  <dt>Expected work</dt><dd><b>${esc(x.display_work)}</b>${x.expected_work?.estimation_method ? `<br><span class="muted">${esc(x.expected_work.estimation_method)}</span>` : ""}${x.expected_work?.note ? `<br><span class="muted">${esc(x.expected_work.note)}</span>` : ""}</dd>
  ${x.probability_model ? `<dt>Probability model</dt><dd>${esc(x.probability_model)}</dd>` : ""}<dt>Parallelisation / overhead</dt><dd>${esc(x.parallelization)} ${esc(x.overhead_assumptions)}</dd>
  <dt>Compute price (optional)</dt><dd>${x.cost ? `${x.cost.core_hours.toPrecision(3)} core-hours ≈ $${x.cost.usd.toPrecision(3)} <span class="muted">${esc(x.cost.note)}</span>` : (x.compute_price ? "price set but work not in seconds" : '<span class="na">not applied</span>')} <button class="sm ghost" onclick="act(()=>api('/api/projects/${pid}/attack-assessments/${x.id}/price',{method:'PATCH',body:{compute_price:{unit:'core_hour',price_usd:parseFloat(prompt('USD per core-hour','0.04'))}}}),'Price set')">set price</button></dd>
  <dt>Uncertainty</dt><dd>${esc(x.uncertainty)}</dd><dt>Applicability limits</dt><dd>${esc(x.applicability_limits)}</dd></dl></div>`;
  return `<h1>Attack-cost research view</h1><p class="sub">Four categories, kept apart. Signing/verification speed is never turned into a breaking time; toy results never infer production-key cost; classical and quantum models are separate; no calendar date for quantum practicality is asserted. Where no defensible estimate exists the view says so.</p>
  ${["A", "B", "C", "D"].map(c => `<h2>${c}. ${esc(a.categories[c])}</h2>${a.items.filter(x => x.category === c).map(card).join("") || '<p class="muted">No entries.</p>'}`).join("")}
  <div class="panel"><h2>Derive a category-B estimate from a measured toy run</h2><p class="muted">Only for synthetic moduli within the toy range; larger targets return “No defensible estimate available”.</p><div class="row"><select id="estrun" style="max-width:420px">${toyRuns.map(r => `<option value="${r.id}">#${r.sequence} ${esc(r.experiment_name)} — ${fmt(r.metrics.iterations_per_second)} it/s</option>`).join("")}</select><input id="estbits" type="number" value="64" style="max-width:120px"> bits <button ${toyRuns.length ? "" : "disabled"} onclick="act(()=>api('/api/projects/${pid}/attack-assessments/estimate-from-run',{method:'POST',body:{measured_run_id:$('#estrun').value,target_modulus_bits:parseInt($('#estbits').value)}}),'Assessment created')">Estimate</button></div></div>
  <div class="panel"><h2>Record an assessment (manual)</h2><form onsubmit="return newAssess(event,'${pid}')"><div class="grid g4"><div><label>Category</label><select name="category"><option>C</option><option>D</option><option>B</option><option>A</option></select></div><div><label>Attack model</label><select name="attack_model"><option>classical</option><option>quantum</option></select></div><div><label>Target</label><input name="target" required></div><div><label>Parameters (JSON)</label><input name="target_parameters" value="{}"></div><div><label>Objective</label><input name="objective"></div><div><label>Attacker capabilities</label><input name="attacker_capabilities"></div><div><label>Method</label><input name="method"></div><div><label>Source</label><input name="source"></div><div><label>Hardware assumptions</label><input name="hardware_assumptions"></div><div><label>Expected work (JSON {value,unit,log2,estimation_method} or blank)</label><input name="expected_work"></div><div><label>Uncertainty</label><input name="uncertainty"></div><div><label>Applicability limits</label><input name="applicability_limits"></div></div><p><button>Record</button></p></form></div>`;
});
window.newAssess = (e, pid) => { e.preventDefault(); const b = Object.fromEntries(new FormData(e.target).entries()); try { b.target_parameters = JSON.parse(b.target_parameters || "{}"); b.expected_work = b.expected_work ? JSON.parse(b.expected_work) : null; } catch { return toast("JSON fields invalid", true), false; } act(() => api(`/api/projects/${pid}/attack-assessments`, {method: "POST", body: b}), "Recorded"); return false; };

// ------------------------------------------------------------------ sandbox
route(/^\/p\/([^/]+)\/sandbox$/, async (pid) => {
  projNav(pid, "/sandbox");
  const [items, allow] = await Promise.all([api(`/api/projects/${pid}/sandbox`), api(`/api/projects/${pid}/sandbox/allowlist`)]);
  return `<h1>Experimental cryptanalysis sandbox</h1><p class="sub">Research-only. Proposals (reproductions, attack improvements, hypotheses, weakness harnesses) are kept separate from executed and verified results. Only approved, allowlisted experiments run — against synthetic/owned/authorized targets, with resource limits, in the isolated runner. Generated arbitrary code never runs.</p>
  <div class="callout">The bundled toy experiment (Pollard rho on ≤64-bit synthetic moduli) demonstrates the workflow. It is not a break of deployed cryptography, and new cryptanalytic ideas are experimental research — not validated discoveries and not protective algorithms.</div>
  <div class="panel"><h2>Allowlist</h2>${Object.entries(allow).map(([k, v]) => `<p><code>${esc(k)}</code> — ${esc(v.description)}<br><span class="muted">bounds ${esc(JSON.stringify(v.bounds))} · target class ${esc(v.target_class)}</span></p>`).join("")}</div>
  <div class="panel"><table><tr><th>Proposal</th><th>Kind</th><th>Executable?</th><th>Target</th><th>Status</th><th>Actions</th></tr>${items.map(s => `<tr><td><b>${esc(s.title)}</b><br><span class="muted">${esc(s.hypothesis)}</span><br><span class="muted" style="font-size:12px">${esc(s.method)}</span><br><span class="muted" style="font-size:11px">proposed by ${esc(s.proposed_by)} · params ${esc(JSON.stringify(s.parameters))} · limits ${esc(JSON.stringify(s.resource_limits))}</span></td><td>${esc(s.kind)}</td><td>${s.allowlisted_fixture ? `<code>${esc(s.allowlisted_fixture)}</code>` : '<span class="warn">no (proposal only)</span>'}</td><td>${esc(s.target_class)}</td><td>${badge(s.status)}${s.run_id ? `<br><a href="#/p/${pid}/runs/${s.run_id}">run</a>` : ""}${s.assessment_id ? `<br><a href="#/p/${pid}/attack">assessment</a>` : ""}</td>
  <td>${s.status === "proposed" ? `<button class="sm" onclick="act(()=>api('/api/projects/${pid}/sandbox/${s.id}/decide',{method:'POST',body:{decision:'approved'}}),'Approved')">approve</button> <button class="sm danger" onclick="act(()=>api('/api/projects/${pid}/sandbox/${s.id}/decide',{method:'POST',body:{decision:'rejected'}}),'Rejected')">reject</button>` : ""}${s.status === "approved" && s.allowlisted_fixture ? `<button class="sm" onclick="act(()=>api('/api/projects/${pid}/sandbox/${s.id}/execute?wait=true',{method:'POST'}),'Executed in isolated runner')">execute</button>` : ""}${s.status === "executed" ? `<button class="sm ghost" onclick="act(()=>api('/api/projects/${pid}/sandbox/${s.id}/verify',{method:'POST',body:{decision:'reviewed',note:prompt('Verification note')||''}}),'Verified')">mark verified</button>` : ""}</td></tr>`).join("") || '<tr><td colspan=6 class="muted">No proposals.</td></tr>'}</table></div>
  <div class="panel"><h2>Propose an experiment</h2><form onsubmit="return newSandbox(event,'${pid}')"><div class="grid g4"><div><label>Title</label><input name="title" required></div><div><label>Kind</label><select name="kind"><option>hypothesis</option><option>reproduction</option><option>attack_improvement</option><option>weakness_harness</option></select></div><div><label>Allowlisted fixture (blank = proposal only)</label><select name="allowlisted_fixture"><option value="">— none —</option>${Object.keys(allow).map(k => `<option>${k}</option>`).join("")}</select></div><div><label>Target class</label><select name="target_class"><option>synthetic</option><option>owned</option><option>authorized</option></select></div></div><label>Hypothesis</label><input name="hypothesis"><label>Method</label><input name="method"><div class="grid g2"><div><label>Parameters (JSON)</label><input name="parameters" value='{"modulus_bits": 40, "trials": 3, "max_iterations": 1000000}'></div><div><label>Resource limits (JSON)</label><input name="resource_limits" value='{"timeout_s": 60, "memory_mb": 256, "cpu_s": 45}'></div></div><p><button>Propose</button></p></form></div>`;
});
window.newSandbox = (e, pid) => { e.preventDefault(); const b = Object.fromEntries(new FormData(e.target).entries()); try { b.parameters = JSON.parse(b.parameters || "{}"); b.resource_limits = JSON.parse(b.resource_limits || "{}"); } catch { return toast("JSON invalid", true), false; } if (!b.allowlisted_fixture) b.allowlisted_fixture = null; act(() => api(`/api/projects/${pid}/sandbox`, {method: "POST", body: b}), "Proposed"); return false; };

// ------------------------------------------------------------------ revalidation history & audit & system
route(/^\/p\/([^/]+)\/revalidation$/, async (pid) => {
  projNav(pid, "/revalidation");
  const h = await api(`/api/projects/${pid}/revalidation`);
  return `<h1>Version-to-version revalidation history</h1><p class="sub">Every implementation version with every run recorded against it. Superseded runs stay visible.</p>
  ${h.map(x => `<div class="panel"><h2>${esc(x.implementation.name)} ${esc(x.implementation.version)} ${badge(x.implementation.role)} ${badge(x.implementation.status)}</h2><p class="muted">${esc(x.implementation.algorithm)} · ${esc(x.implementation.library)} ${esc(x.implementation.library_version)} · <code>${esc(x.implementation.source_revision)}</code></p>
  <table><tr><th>#</th><th>Experiment</th><th>Runner / fixture version</th><th>Provenance</th><th>Status</th><th>Result</th><th>Failed requirements</th><th>Failed scenarios</th><th>Supersedes</th><th>When</th></tr>${x.runs.map(r => `<tr class="clickable" onclick="location.hash='#/p/${pid}/runs/${r.id}'"><td>${r.sequence}</td><td>${esc(r.experiment)}</td><td>${esc(r.runner_kind)} ${esc(r.runner_version)} / ${esc(r.fixture_version)}</td><td>${prov(r.provenance)}</td><td>${badge(r.status)}</td><td>${passmark(r.overall_pass)}</td><td class="bad" style="font-size:12px">${esc(r.failed_requirements.join(", "))}</td><td class="bad" style="font-size:12px">${esc(r.failed_scenarios.join(", "))}</td><td>${r.supersedes_run_id ? "yes" : ""}</td><td class="muted">${when(r.created_at)}</td></tr>`).join("") || '<tr><td colspan=10 class="muted">No runs.</td></tr>'}</table></div>`).join("")}`;
});
route(/^\/p\/([^/]+)\/audit$/, async (pid) => {
  projNav(pid, "/audit");
  const ev = await api(`/api/projects/${pid}/audit`);
  return `<h1>Audit history</h1><p class="sub">Who did what, when. Secrets are redacted before storage.</p><div class="panel"><table><tr><th>When</th><th>Actor</th><th>Action</th><th>Subject</th><th>Detail</th></tr>${ev.map(e => `<tr><td class="muted">${when(e.created_at)}</td><td>${esc(e.actor || "system")}</td><td><code>${esc(e.action)}</code></td><td>${esc(e.subject_type)} <span class="muted">${esc((e.subject_id || "").slice(0, 8))}</span></td><td><code style="font-size:11px">${esc(JSON.stringify(e.detail))}</code></td></tr>`).join("")}</table></div>`;
});
route(/^\/system$/, async () => {
  $("#projnav").innerHTML = "";
  const [runners, cat, jobs] = await Promise.all([api("/api/runners"), api("/api/catalog"), api("/api/jobs")]);
  return `<h1>System</h1><p class="sub">What is implemented and tested here versus interface-only. Nothing below claims tenant isolation, hardware support, CI integration or automated deployment.</p>
  <div class="panel"><h2>Runners</h2><table><tr><th>Kind</th><th>Version</th><th>Provenance</th><th>Available</th><th>Implemented</th><th>Tested in this environment</th><th>Description</th></tr>${runners.map(r => `<tr><td><code>${esc(r.kind)}</code></td><td>${esc(r.version)}</td><td>${prov(r.provenance)}</td><td>${r.available ? '<span class="ok">yes</span>' : `<span class="bad">no</span> <span class="muted">${esc(r.unavailable_reason)}</span>`}</td><td>${r.implemented ? "yes" : '<span class="warn">interface only</span>'}</td><td>${r.tested_in_this_environment ? "yes" : '<span class="warn">no</span>'}</td><td class="muted">${esc(r.description)}</td></tr>`).join("")}</table></div>
  <div class="panel"><h2>Curated catalog (${esc(cat.catalog_date)})</h2><table><tr><th>Profile</th><th>Purpose</th><th>Family</th><th>Standards</th><th>Sizes</th><th>Fixture</th><th>Notes</th></tr>${cat.profiles.map(p => `<tr><td><b>${esc(p.label)}</b><br><code>${esc(p.id)}</code></td><td>${esc(p.purpose)}</td><td>${esc(p.family)}</td><td style="font-size:12px">${esc(p.standards.join("; "))}</td><td><code style="font-size:11px">${esc(JSON.stringify(p.sizes))}</code></td><td>${p.fixture ? `<code>${esc(p.fixture)}</code>` : '<span class="warn">none (import only)</span>'}</td><td class="muted" style="font-size:12px">${esc(p.quantum)}</td></tr>`).join("")}</table></div>
  <div class="panel"><h2>Background jobs</h2><table><tr><th>Kind</th><th>Status</th><th>Attempts</th><th>Error</th><th>When</th></tr>${jobs.map(j => `<tr><td>${esc(j.kind)}</td><td>${badge(j.status)}</td><td>${j.attempts}</td><td class="bad" style="font-size:11px">${esc((j.error || "").slice(0, 200))}</td><td class="muted">${when(j.created_at)}</td></tr>`).join("")}</table></div>`;
});

render();
